from bilateral_core import *

def main():
 dest=U/'web';dest.mkdir(exist_ok=True)
 html=(U/'before_web/index.html').read_text('utf-8');app=(U/'before_web/app.js').read_text('utf-8');css=(U/'before_web/style.css').read_text('utf-8')
 start=html.index('<div class="timeline">');end=html.index('<p id="timing"',start)
 html=html[:start]+'''<div class="timelineRows"><div class="tracklabel">동작 구간</div><div id="stageBands" class="track"></div><div class="tracklabel">확인 결과</div><div id="bands" class="track"></div></div><input id="seek" type="range" min="0" max="1000" step="1" value="0" aria-label="두 시간띠의 비교 순간"><p id="stageNote" class="small"></p><div class="legend small">청록: 확인한 특징이 비슷함 · 주황: 차이 근거 · 빗금: 근거 부족(오답 아님) · 빈 곳: 검사하지 않은 구간</div>
 <section id="evidenceDetails" hidden><div id="components"></div><p id="evidenceScope" class="small"></p><p id="arrowNote" class="small"></p><details id="handZoom" hidden><summary>해당 손 크게 보기</summary><div class="zoomrow"><figure><canvas id="refZoom"></canvas><figcaption>참고 손</figcaption></figure><figure><canvas id="queryZoom"></canvas><figcaption>관측한 손</figcaption></figure></div><p id="zoomNote" class="small"></p></details></section>
 '''+html[end:]
 ext=(U/'evidence_view.js').read_text('utf-8').replace('未검사','미검사').replace('確認','확인')
 app=app.replace('init().catch',ext+'\ninit().catch')
 css+='''\n.timelineRows{display:grid;grid-template-columns:64px 1fr;gap:5px 8px;margin-top:10px}.tracklabel{font-size:11px;line-height:18px;color:#334b66}.track{position:relative;height:18px;background:#eef1f5;border:1px solid #ccd5e0;border-radius:3px;overflow:hidden}#bands.track{position:relative;inset:auto;height:18px}.trackpart{position:absolute;top:0;height:100%;padding:0;border:0;border-radius:0;min-width:1px}.trackpart.mainstage{background:#5676bc}.trackpart.similar{background:#008577}.trackpart.difference{background:#d87911}.trackpart.uncertain{background:repeating-linear-gradient(135deg,#8b95a5 0 4px,#e1e5ed 4px 7px)}.trackpart.outside{background:#eef1f5}#seek{width:calc(100% - 72px);margin-left:72px}#components{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.component{font-size:11px;border:1px solid #aab9cc;border-radius:16px;padding:5px 10px;background:white;color:#425971}.component.supported{border-color:#008577;color:#006d5d}.component.contradicted{border-color:#d87911;color:#905000}.component.unconfirmed{background:#f0f3f8}.zoomrow{display:grid;grid-template-columns:1fr 1fr;gap:12px}.zoomrow figure{margin:10px 0 0;text-align:center;background:#e9eef6;border-radius:8px}.zoomrow canvas{width:100%;max-width:210px;height:125px}.zoomrow figcaption{font-size:11px;padding:4px}#handZoom{margin-top:8px;padding-top:7px}#evidenceDetails{padding:1px 8px 6px;border-left:3px solid #b8c6d8;margin-top:8px}#stageNote{margin-bottom:3px}@media(max-width:500px){.timelineRows{grid-template-columns:54px 1fr}#seek{width:calc(100% - 62px);margin-left:62px}.tracklabel{font-size:10px}}\n'''
 css+='''\n@media(min-width:761px) and (max-height:950px){main{padding-top:10px}header{margin-bottom:6px}h1{font-size:22px}.toolbar button,.toolbar select{padding:7px 11px}.hint{margin:6px 0;font-size:12px}.frame{height:180px}.videohead{padding:7px 12px}.ranks{margin:8px 0;padding:6px}.resulthead{margin-top:7px}h2{font-size:17px}.notice{padding:5px 10px;margin:5px 0 7px}.cards .card{min-height:56px;padding:7px 10px}.card b{font-size:14px}.card span{margin-bottom:3px}aside{padding:7px 12px;margin-top:7px}aside .instruction{font-size:13px}.playbar{margin-top:8px}.timelineRows{margin-top:6px;gap:3px 8px}.track,#bands.track{height:14px}.tracklabel{line-height:14px}#evidenceDetails{margin-top:5px}#components{margin-top:5px}.component{padding:3px 9px}#stageNote,.legend.small{margin-top:3px}}\n'''
 for name,data in [('index.html',html),('app.js',app),('style.css',css)]:(dest/name).write_text(data,'utf-8')
 write(U/'WEB_CANDIDATE.json',dict(files={str(dest/f):sha(dest/f) for f in ['index.html','app.js','style.css']},model_changed=False,verdict_changed=False,uses_only_existing_evidence=True))
if __name__=='__main__':main()
